UiSurfaceStyle gUiSurfaceStyle = UiSurfaceStyle::Solid;
int gUiSurfaceOpacity = 100;

enum class UiSurfaceRole
{
    None,
    Header,
    Panel,
    Input,
    Control,
    Dropdown
};

void ApplyUiSurfaceAppearance(const AppearanceSettings& appearance)
{
    gUiSurfaceStyle = appearance.uiSurfaceStyle;
    gUiSurfaceOpacity = std::clamp(appearance.uiSurfaceOpacity, 35, 100);
}

UiSurfaceRole UiSurfaceRoleForColor(COLORREF color)
{
    if (color == kSidebarBackground || color == kPanelBackground || color == kPanelHover)
    {
        return UiSurfaceRole::Panel;
    }
    if (color == kInputBackground)
    {
        return UiSurfaceRole::Input;
    }
    if (color == kButtonBackground || color == kButtonHover ||
        color == kButtonPressed || color == kDisabledBackground)
    {
        return UiSurfaceRole::Control;
    }
    if (color == kDropdownBackground || color == kDropdownHover || color == kDropdownSelected)
    {
        return UiSurfaceRole::Dropdown;
    }
    return UiSurfaceRole::None;
}

int UiSurfaceOpacityForRole(UiSurfaceRole role)
{
    if (gUiSurfaceStyle == UiSurfaceStyle::Solid || role == UiSurfaceRole::None)
    {
        return 100;
    }

    const int strength = std::clamp(gUiSurfaceOpacity, 35, 100);
    if (gUiSurfaceStyle == UiSurfaceStyle::Translucent)
    {
        switch (role)
        {
        case UiSurfaceRole::Header:
            return std::clamp(45 + strength * 43 / 100, 60, 88);
        case UiSurfaceRole::Panel:
            return std::clamp(45 + strength * 48 / 100, 62, 93);
        case UiSurfaceRole::Control:
            return std::clamp(56 + strength * 38 / 100, 69, 94);
        case UiSurfaceRole::Input:
            return std::clamp(82 + strength * 16 / 100, 87, 98);
        case UiSurfaceRole::Dropdown:
            return std::clamp(84 + strength * 14 / 100, 88, 98);
        default:
            return 100;
        }
    }

    switch (role)
    {
    case UiSurfaceRole::Header:
        return std::clamp(28 + strength * 34 / 100, 40, 62);
    case UiSurfaceRole::Panel:
        return std::clamp(32 + strength * 38 / 100, 45, 70);
    case UiSurfaceRole::Control:
        return std::clamp(48 + strength * 34 / 100, 60, 82);
    case UiSurfaceRole::Input:
        return std::clamp(78 + strength * 18 / 100, 84, 96);
    case UiSurfaceRole::Dropdown:
        return std::clamp(80 + strength * 18 / 100, 86, 98);
    default:
        return 100;
    }
}

