std::wstring ToolkitApp::MacroRecordHotkeyLabel() const
{
    if (awaitingMacroRecordHotkey_)
    {
        return L"Press a key...";
    }
    return MacroHotkeyService::HotkeyLabel(macroRecordHotkey_);
}

std::wstring ToolkitApp::MacroPlayHotkeyLabel() const
{
    if (awaitingMacroPlayHotkey_)
    {
        return L"Press a key...";
    }
    return MacroHotkeyService::HotkeyLabel(macroPlayHotkey_);
}

std::wstring ToolkitApp::MacroStopHotkeyLabel() const
{
    if (awaitingMacroStopHotkey_)
    {
        return L"Press a key...";
    }
    return MacroHotkeyService::HotkeyLabel(macroStopHotkey_);
}

std::wstring ToolkitApp::MacroMouseModeLabel() const
{
    switch (macroRecordingMode_.mouseMode)
    {
    case MacroMouseMode::Absolute:
        return L"Absolute screen";
    case MacroMouseMode::WindowRelative:
        return L"Window-relative";
    case MacroMouseMode::Relative:
        break;
    }
    return L"Relative";
}

std::wstring ToolkitApp::MacroCaptureRateLabel() const
{
    return std::to_wstring(macroRecordingMode_.captureRateHz) + L" Hz";
}

std::wstring ToolkitApp::MacroPlaybackSpeedLabel() const
{
    std::wostringstream stream;
    stream << std::fixed << std::setprecision(1) << macroPlaybackOptions_.speed << L"x";
    return stream.str();
}

std::wstring ToolkitApp::MacroPlaybackBackendLabel() const
{
    return macroPlaybackOptions_.backend == MacroPlaybackBackend::Interception
        ? L"Driver-enhanced"
        : L"Standard";
}

std::wstring ToolkitApp::MacroLoopModeLabel() const
{
    if (macroPlaybackOptions_.loopUntilStopped)
    {
        return L"Until stopped";
    }
    const int loopCount = std::clamp(macroPlaybackOptions_.loopCount, 1, 999);
    if (loopCount <= 1)
    {
        return L"No loop";
    }
    return L"Play " + std::to_wstring(loopCount) + L" times";
}

std::wstring ToolkitApp::MacroStartDelayLabel() const
{
    if (macroPlaybackOptions_.startDelaySeconds <= 0)
    {
        return L"No delay";
    }
    return std::to_wstring(macroPlaybackOptions_.startDelaySeconds) + L" seconds";
}

std::wstring ToolkitApp::MacroRecorderStatusLabel() const
{
    if (macroRecorderService_.IsRecording())
    {
        return L"Recording";
    }
    if (macroRecorderArmed_)
    {
        return L"Armed";
    }
    if (macroHasPendingRecording_)
    {
        return L"Stopped";
    }
    return L"Idle";
}

std::wstring ToolkitApp::MacroPlaybackStatusLabel() const
{
    MacroPlaybackSnapshot snapshot = macroPlaybackService_.Snapshot();
    std::wstring label = snapshot.message.empty() ? L"Playback idle." : snapshot.message;
    if (snapshot.currentLoop > 0)
    {
        label += L" Loop ";
        label += std::to_wstring(snapshot.currentLoop);
        if (snapshot.requestedLoops > 0)
        {
            label += L" of " + std::to_wstring(snapshot.requestedLoops);
        }
    }
    return label;
}

double ToolkitApp::MacroPlaybackProgress() const
{
    MacroPlaybackSnapshot snapshot = macroPlaybackService_.Snapshot();
    if (snapshot.totalUs <= 0)
    {
        return 0.0;
    }
    return static_cast<double>(snapshot.elapsedUs % snapshot.totalUs) / static_cast<double>(snapshot.totalUs);
}

const MacroDefinition* ToolkitApp::MacroForPlayback() const
{
    if (macroHasPendingRecording_ && !pendingRecordedMacro_.events.empty())
    {
        return &pendingRecordedMacro_;
    }

    return SelectedMacro();
}

const MacroDefinition* ToolkitApp::SelectedMacro() const
{
    if (selectedMacroIndex_ < 0 || selectedMacroIndex_ >= static_cast<int>(macros_.size()))
    {
        return nullptr;
    }
    return &macros_[static_cast<size_t>(selectedMacroIndex_)];
}

MacroDefinition* ToolkitApp::SelectedMacro()
{
    if (selectedMacroIndex_ < 0 || selectedMacroIndex_ >= static_cast<int>(macros_.size()))
    {
        return nullptr;
    }
    return &macros_[static_cast<size_t>(selectedMacroIndex_)];
}

RECT ToolkitApp::MacroListRowRect(size_t index) const
{
    const int rowHeight = Dips(56);
    const int rowTop = macroNewButtonRect_.bottom + Dips(14) + static_cast<int>(index) * (rowHeight + Dips(6));
    return {
        macroListPanelRect_.left + Dips(14),
        rowTop,
        macroListPanelRect_.right - Dips(14),
        rowTop + rowHeight
    };
}

void ToolkitApp::CreateVideoCompressorControls()
{
    videoCompressorTargetEdit_ = CreateWindowExW(
        0,
        L"EDIT",
        L"",
        WS_CHILD | WS_TABSTOP | ES_AUTOHSCROLL,
        0,
        0,
        0,
        0,
        hwnd_,
        nullptr,
        instance_,
        nullptr);
    if (!videoCompressorTargetEdit_)
    {
        return;
    }
    SendMessageW(videoCompressorTargetEdit_, WM_SETFONT, reinterpret_cast<WPARAM>(searchInputFont_), TRUE);
    SendMessageW(videoCompressorTargetEdit_, EM_SETMARGINS, EC_LEFTMARGIN | EC_RIGHTMARGIN, MAKELPARAM(Dips(8), Dips(6)));
    SendMessageW(videoCompressorTargetEdit_, EM_LIMITTEXT, 12, 0);
    const double displayValue = videoCompressorTargetInGb_
        ? static_cast<double>(videoCompressionOptions_.targetSizeBytes) / (1024.0 * 1024.0 * 1024.0)
        : static_cast<double>(videoCompressionOptions_.targetSizeBytes) / (1024.0 * 1024.0);
    std::wostringstream value;
    value << std::fixed << std::setprecision(videoCompressorTargetInGb_ ? 2 : 0) << displayValue;
    SetWindowTextW(videoCompressorTargetEdit_, value.str().c_str());
}

void ToolkitApp::UpdateVideoCompressorControls()
{
    if (!videoCompressorTargetEdit_)
    {
        return;
    }
    const bool visible = currentPage_ == Page::Tool && currentTool_ == ToolKind::VideoCompressor &&
        videoAnalysis_.width > 0 && videoAnalysis_.height > 0 &&
        !liveResize_ && !smoothScrollActive_ && !scrollBarDragging_;
    const bool coveredByDropdown = activeDropdown_ != DropdownKind::None &&
        HasArea(dropdownRect_) && RectsOverlap(videoCompressorTargetEditRect_, dropdownRect_);
    const bool shouldDisplay = visible && !coveredByDropdown &&
        RectsOverlap(videoCompressorTargetEditRect_, contentRect_);
    const int inset = Dips(10);
    const int height = Dips(24);
    SetChildWindowViewportLayout(
        videoCompressorTargetEdit_,
        videoCompressorTargetEditRect_.left + inset,
        videoCompressorTargetEditRect_.top + ((videoCompressorTargetEditRect_.bottom - videoCompressorTargetEditRect_.top) - height) / 2 + Dips(2),
        std::max(1, static_cast<int>(videoCompressorTargetEditRect_.right - videoCompressorTargetEditRect_.left) - inset * 2),
        height,
        contentRect_,
        shouldDisplay,
        !videoCompressorAnalyzing_ && !videoCompressorCompressing_);
}

void ToolkitApp::BrowseVideoCompressorInput()
{
    if (videoCompressorAnalyzing_ || videoCompressorCompressing_)
    {
        return;
    }
    wchar_t fileBuffer[32768] {};
    OPENFILENAMEW dialog {};
    dialog.lStructSize = sizeof(dialog);
    dialog.hwndOwner = hwnd_;
    dialog.lpstrFilter = L"Video files (*.mp4;*.mov;*.mkv;*.webm;*.avi;*.m4v)\0*.mp4;*.mov;*.mkv;*.webm;*.avi;*.m4v\0All files (*.*)\0*.*\0\0";
    dialog.lpstrFile = fileBuffer;
    dialog.nMaxFile = static_cast<DWORD>(std::size(fileBuffer));
    dialog.Flags = OFN_FILEMUSTEXIST | OFN_PATHMUSTEXIST | OFN_EXPLORER;
    dialog.lpstrTitle = L"Choose a video to compress";
    if (GetOpenFileNameW(&dialog))
    {
        SelectVideoCompressorInput(fileBuffer);
    }
}

void ToolkitApp::SelectVideoCompressorInput(const std::filesystem::path& path)
{
    if (videoCompressorAnalyzing_ || videoCompressorCompressing_)
    {
        return;
    }
    if (!VideoCompressionService::IsSupportedInput(path))
    {
        videoCompressorStatusText_ = L"Choose an MP4, MOV, MKV, WEBM, AVI, or M4V video.";
        InvalidateRect(hwnd_, nullptr, FALSE);
        return;
    }
    StartVideoCompressorAnalysis(path);
}

void ToolkitApp::ClearVideoCompressorInput()
{
    if (videoCompressorAnalyzing_ || videoCompressorCompressing_)
    {
        return;
    }
    videoAnalysis_ = {};
    videoCompressionPlan_ = {};
    videoCompressionProgress_ = {};
    videoCompressionResult_ = {};
    videoCompressorStatusText_ = L"Choose a video to begin.";
    RecalculateLayout();
    InvalidateRect(hwnd_, nullptr, FALSE);
}

void ToolkitApp::BrowseVideoCompressorOutputFolder()
{
    if (videoCompressorAnalyzing_ || videoCompressorCompressing_)
    {
        return;
    }
    BROWSEINFOW browseInfo {};
    browseInfo.hwndOwner = hwnd_;
    browseInfo.lpszTitle = L"Choose where to save compressed videos";
    browseInfo.ulFlags = BIF_RETURNONLYFSDIRS | BIF_USENEWUI;
    const std::wstring initialFolder = videoCompressionOptions_.outputFolder.wstring();
    if (!initialFolder.empty())
    {
        browseInfo.lpfn = BrowseFolderCallback;
        browseInfo.lParam = reinterpret_cast<LPARAM>(initialFolder.c_str());
    }
    PIDLIST_ABSOLUTE itemList = SHBrowseForFolderW(&browseInfo);
    if (!itemList)
    {
        return;
    }
    wchar_t path[MAX_PATH] {};
    if (SHGetPathFromIDListW(itemList, path))
    {
        videoCompressionOptions_.outputFolder = path;
        SaveVideoCompressorSettings();
        videoCompressorStatusText_ = L"Output folder selected.";
        InvalidateRect(hwnd_, nullptr, FALSE);
    }
    CoTaskMemFree(itemList);
}

void ToolkitApp::StartVideoCompressorAnalysis(const std::filesystem::path& path)
{
    videoCompressionExternalTools_ = videoCompressionService_.CheckExternalTools();
    if (!videoCompressionExternalTools_.ffmpegFound || !videoCompressionExternalTools_.ffprobeFound)
    {
        videoCompressorStatusText_ = !videoCompressionExternalTools_.ffprobeFound
            ? L"FFprobe is missing. Restore the bundled tools folder before analyzing videos."
            : L"FFmpeg is missing. Restore the bundled tools folder before compressing videos.";
        InvalidateRect(hwnd_, nullptr, FALSE);
        return;
    }
    FinishVideoCompressorThread();
    videoCompressionCancelRequested_ = false;
    videoCompressorAnalyzing_ = true;
    videoAnalysis_ = {};
    videoAnalysis_.filePath = path;
    videoAnalysis_.fileName = path.filename().wstring();
    videoCompressionPlan_ = {};
    videoCompressionResult_ = {};
    videoCompressionProgress_ = { VideoCompressionPhase::Analyzing };
    videoCompressorStatusText_ = L"Analyzing video with FFprobe...";
    UpdateVideoCompressorControls();
    InvalidateRect(hwnd_, nullptr, FALSE);

    HWND hwnd = hwnd_;
    videoCompressionThread_ = std::thread([this, hwnd, path]()
    {
        auto* result = new VideoCompressionAnalysisThreadResult();
        try
        {
            result->analysis = videoCompressionService_.Analyze(path, videoCompressionCancelRequested_, result->errorMessage);
        }
        catch (...)
        {
            result->analysis = {};
            result->errorMessage = L"The video could not be analyzed because an unexpected file or system error occurred.";
        }
        if (!PostMessageW(hwnd, kVideoCompressionAnalysisFinishedMessage, 0, reinterpret_cast<LPARAM>(result)))
        {
            delete result;
        }
    });
}

void ToolkitApp::StartVideoCompression()
{
    if (videoCompressorAnalyzing_ || videoCompressorCompressing_ || videoAnalysis_.filePath.empty())
    {
        return;
    }
    RecalculateVideoCompressionPlan();
    if (!videoCompressionPlan_.valid)
    {
        videoCompressorStatusText_ = videoCompressionPlan_.errorMessage.empty() ? L"Choose a valid target size." : videoCompressionPlan_.errorMessage;
        InvalidateRect(hwnd_, nullptr, FALSE);
        return;
    }
    std::error_code outputFolderError;
    const bool outputFolderExists = !videoCompressionOptions_.outputFolder.empty() &&
        std::filesystem::exists(videoCompressionOptions_.outputFolder, outputFolderError);
    const bool outputFolderIsDirectory = outputFolderExists &&
        std::filesystem::is_directory(videoCompressionOptions_.outputFolder, outputFolderError);
    if (outputFolderError || !outputFolderIsDirectory)
    {
        videoCompressorStatusText_ = L"Choose a valid output folder.";
        InvalidateRect(hwnd_, nullptr, FALSE);
        return;
    }

    FinishVideoCompressorThread();
    videoCompressionCancelRequested_ = false;
    videoCompressorCompressing_ = true;
    videoCompressionResult_ = {};
    videoCompressionProgress_ = { VideoCompressionPhase::Calculating };
    videoCompressorStatusText_ = L"Calculating compression settings...";
    SaveVideoCompressorSettings();
    UpdateVideoCompressorControls();
    InvalidateRect(hwnd_, nullptr, FALSE);

    const VideoAnalysis analysis = videoAnalysis_;
    const VideoCompressionOptions options = videoCompressionOptions_;
    const std::filesystem::path outputPath = VideoCompressionService::DefaultOutputPath(analysis, options);
    HWND hwnd = hwnd_;
    videoCompressionThread_ = std::thread([this, hwnd, analysis, options, outputPath]()
    {
        VideoCompressionResult result;
        try
        {
            result = videoCompressionService_.Compress(
                analysis,
                options,
                outputPath,
                videoCompressionCancelRequested_,
                [hwnd](const VideoCompressionProgress& progress)
                {
                    auto* update = new VideoCompressionProgress(progress);
                    if (!PostMessageW(hwnd, kVideoCompressionProgressMessage, 0, reinterpret_cast<LPARAM>(update)))
                    {
                        delete update;
                    }
                });
        }
        catch (...)
        {
            result.originalSizeBytes = analysis.fileSizeBytes;
            result.errorMessage = L"Compression stopped because an unexpected file or system error occurred. The original video was not changed.";
        }
        auto* finalResult = new VideoCompressionResult(std::move(result));
        if (!PostMessageW(hwnd, kVideoCompressionFinishedMessage, 0, reinterpret_cast<LPARAM>(finalResult)))
        {
            delete finalResult;
        }
    });
}

void ToolkitApp::CancelVideoCompression()
{
    if (!videoCompressorCompressing_)
    {
        return;
    }
    videoCompressionCancelRequested_ = true;
    videoCompressorStatusText_ = L"Cancelling and cleaning up...";
    InvalidateRect(hwnd_, nullptr, FALSE);
}

void ToolkitApp::FinishVideoCompressorThread()
{
    if (videoCompressionThread_.joinable() && videoCompressionThread_.get_id() != std::this_thread::get_id())
    {
        videoCompressionThread_.join();
    }
}

void ToolkitApp::ApplyVideoCompressionProgress(const VideoCompressionProgress& progress)
{
    videoCompressionProgress_ = progress;
    videoCompressorStatusText_ = progress.message.empty() ? VideoCompressionService::PhaseLabel(progress.phase) : progress.message;
    InvalidateRect(hwnd_, nullptr, FALSE);
}

void ToolkitApp::ApplyVideoCompressionResult(const VideoCompressionResult& result)
{
    videoCompressionResult_ = result;
    videoCompressionPlan_ = result.plan;
    if (result.success)
    {
        videoCompressionProgress_.phase = VideoCompressionPhase::Complete;
        videoCompressionProgress_.progress = 1.0;
        videoCompressorStatusText_ = L"Compression complete.";
    }
    else if (result.cancelled)
    {
        videoCompressionProgress_.phase = VideoCompressionPhase::Cancelled;
        videoCompressionProgress_.progress = 0.0;
        videoCompressorStatusText_ = L"Compression cancelled. Temporary files were removed.";
    }
    else
    {
        videoCompressionProgress_.phase = VideoCompressionPhase::Failed;
        videoCompressionProgress_.progress = 0.0;
        videoCompressorStatusText_ = result.errorMessage.empty() ? L"Compression failed." : result.errorMessage;
    }
}

unsigned long long ToolkitApp::VideoCompressorTargetBytes() const
{
    if (!videoCompressorTargetEdit_)
    {
        return videoCompressionOptions_.targetSizeBytes;
    }
    try
    {
        const std::wstring text = TrimWhitespace(GetWindowTextString(videoCompressorTargetEdit_));
        size_t parsedCharacters = 0;
        const long double value = std::stold(text, &parsedCharacters);
        if (!std::isfinite(static_cast<double>(value)) || value <= 0.0L || value > 100000.0L)
        {
            return 0;
        }
        if (parsedCharacters != text.size())
        {
            return 0;
        }
        const long double multiplier = videoCompressorTargetInGb_
            ? 1024.0L * 1024.0L * 1024.0L
            : 1024.0L * 1024.0L;
        const long double bytes = value * multiplier;
        if (!std::isfinite(bytes) || bytes > static_cast<long double>(kMaximumVideoCompressionTargetBytes))
        {
            return 0;
        }
        return static_cast<unsigned long long>(bytes);
    }
    catch (...)
    {
        return 0;
    }
}

void ToolkitApp::RecalculateVideoCompressionPlan()
{
    if (videoAnalysis_.filePath.empty())
    {
        videoCompressionPlan_ = {};
        return;
    }
    videoCompressionOptions_.targetSizeBytes = VideoCompressorTargetBytes();
    videoCompressionPlan_ = videoCompressionService_.Plan(videoAnalysis_, videoCompressionOptions_);
}

