std::wstring ToolkitApp::VideoCompressorSettingsFilePath() const
{
    return SettingsDirectory() + L"\\video_compressor.txt";
}

void ToolkitApp::LoadVideoCompressorSettings()
{
    std::wifstream input(VideoCompressorSettingsFilePath());
    if (!input)
    {
        return;
    }
    std::wstring folder;
    int mode = 0;
    int resolution = 0;
    int fps = 0;
    int audio = 0;
    int preset = 0;
    int conflict = 0;
    int verify = 1;
    int retry = 1;
    int metadata = 0;
    int inGb = 0;
    int encoder = 0;
    unsigned long long target = videoCompressionOptions_.targetSizeBytes;
    input >> std::quoted(folder) >> target >> mode >> resolution >> fps >> audio >> preset >> conflict >> verify >> retry >> metadata >> inGb;
    if (!input)
    {
        return;
    }
    videoCompressionOptions_.outputFolder = folder;
    videoCompressionOptions_.targetSizeBytes = std::clamp(
        target,
        1024ULL * 1024ULL,
        kMaximumVideoCompressionTargetBytes);
    videoCompressionOptions_.mode = static_cast<VideoCompressionMode>(std::clamp(mode, 0, 1));
    videoCompressionOptions_.resolutionMode = static_cast<VideoResolutionMode>(std::clamp(resolution, 0, 4));
    videoCompressionOptions_.fpsMode = static_cast<VideoFpsMode>(std::clamp(fps, 0, 4));
    videoCompressionOptions_.audioMode = static_cast<VideoAudioMode>(std::clamp(audio, 0, 6));
    videoCompressionOptions_.preset = static_cast<VideoEncodingPreset>(std::clamp(preset, 0, 2));
    videoCompressionOptions_.conflictBehavior = static_cast<VideoConflictBehavior>(std::clamp(conflict, 0, 1));
    videoCompressionOptions_.verifyFinalSize = verify != 0;
    videoCompressionOptions_.retryIfTooLarge = retry != 0;
    videoCompressionOptions_.preserveMetadata = metadata != 0;
    videoCompressorTargetInGb_ = inGb != 0;
    if (input >> encoder)
    {
        videoCompressionOptions_.encoderMode = static_cast<VideoEncoderMode>(std::clamp(encoder, 0, 1));
    }
}

void ToolkitApp::SaveVideoCompressorSettings() const
{
    std::error_code error;
    std::filesystem::create_directories(SettingsDirectory(), error);
    std::wofstream output(VideoCompressorSettingsFilePath(), std::ios::trunc);
    if (!output)
    {
        return;
    }
    output << std::quoted(videoCompressionOptions_.outputFolder.wstring()) << L' '
        << videoCompressionOptions_.targetSizeBytes << L' '
        << static_cast<int>(videoCompressionOptions_.mode) << L' '
        << static_cast<int>(videoCompressionOptions_.resolutionMode) << L' '
        << static_cast<int>(videoCompressionOptions_.fpsMode) << L' '
        << static_cast<int>(videoCompressionOptions_.audioMode) << L' '
        << static_cast<int>(videoCompressionOptions_.preset) << L' '
        << static_cast<int>(videoCompressionOptions_.conflictBehavior) << L' '
        << (videoCompressionOptions_.verifyFinalSize ? 1 : 0) << L' '
        << (videoCompressionOptions_.retryIfTooLarge ? 1 : 0) << L' '
        << (videoCompressionOptions_.preserveMetadata ? 1 : 0) << L' '
        << (videoCompressorTargetInGb_ ? 1 : 0) << L' '
        << static_cast<int>(videoCompressionOptions_.encoderMode) << L'\n';
}

