void ToolkitApp::UpdateFileConverterSummary()
{
    if (conversionJobs_.empty())
    {
        fileConverterSummary_ = L"Ready.";
        return;
    }

    int complete = 0;
    int failed = 0;
    int skipped = 0;
    int converting = 0;
    for (const ConversionJob& job : conversionJobs_)
    {
        if (job.status == ConversionStatus::Complete)
        {
            ++complete;
        }
        else if (job.status == ConversionStatus::Failed)
        {
            ++failed;
        }
        else if (job.status == ConversionStatus::Skipped)
        {
            ++skipped;
        }
        else if (job.status == ConversionStatus::Converting)
        {
            ++converting;
        }
    }

    std::wostringstream summary;
    if (fileConverterConverting_ || converting > 0)
    {
        summary << L"Converting... ";
    }
    summary << L"Converted " << complete << L" successfully.";
    if (failed > 0)
    {
        summary << L" " << failed << L" failed.";
    }
    if (skipped > 0)
    {
        summary << L" " << skipped << L" skipped.";
    }
    fileConverterSummary_ = summary.str();
}

int ToolkitApp::VisibleConverterQueueRows() const
{
    return static_cast<int>(conversionJobs_.size());
}

RECT ToolkitApp::ConverterQueueRowRect(size_t visibleIndex) const
{
    const int rowTop =
        converterQueueRect_.top + Dips(62) +
        static_cast<int>(visibleIndex) * Dips(58);
    return {
        converterQueueRect_.left + Dips(12),
        rowTop,
        converterQueueRect_.right - Dips(12),
        rowTop + Dips(50)
    };
}

RECT ToolkitApp::ConverterQueueRemoveRect(size_t visibleIndex) const
{
    const RECT row = ConverterQueueRowRect(visibleIndex);
    return {
        row.right - Dips(42),
        row.top + Dips(8),
        row.right - Dips(8),
        row.bottom - Dips(8)
    };
}
